#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.16.0  -  Sign-up steps, smooth video timeline, pinned comments, QR profile
#   * Create account: Choose language first, then country (searchable) and a required
#     tick for the Privacy policy and Terms of use.
#   * Video editor: the timeline is always in view, smooth, with lanes for audio, texts
#     and stickers (drag a bar to move it, drag its ends to set when it shows).
#   * Moments: texts and stickers can be resized (frame, corner handle, size bar).
#   * Comments: the owner of a post can pin up to 3 comments.
#   * Clips: Follow without the lime fill, Mute / Unmute in the button column, repost
#     count under Repost (also on post cards).
#   * Followers / Following: smaller words on the button.
#   * Share profile: QR code, link, username and a Share button.
#   * Videos are limited to 1 minute.
#   * Privacy Policy and Terms of Use pages in docs/ (GitHub Pages).
# Run from the project root:   bash update_v1160_signup_timeline_pins_qr.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="733e9857316d9ac9efdfc215a071985c45bcd61e9181487605e271a120ca2d8f"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/widgets/comment_tile.dart ] || { echo "ERROR: v1.15.0 is not installed. Run update_v1150_comments_stickers_timeline.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Adding the QR code package to pubspec.yaml..."
python3 - pubspec.yaml <<'PYX'
import re, sys
p = sys.argv[1]
s = open(p).read()
if re.search(r"^[ \t]+qr_flutter:", s, re.M):
    print("    pubspec.yaml: qr_flutter already there")
else:
    m = re.search(r"^dependencies:[ \t]*\r?\n", s, re.M)
    if not m:
        sys.exit("ERROR: no dependencies: section in pubspec.yaml")
    s = s[:m.end()] + "  qr_flutter: ^4.1.0\n" + s[m.end():]
    open(p, "w").write(s)
    print("    pubspec.yaml: added qr_flutter")
PYX

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.16.0 is in place."
echo ""
echo "IMPORTANT (once):"
echo "  1) Firestore rules: Firebase console -> Firestore Database -> Rules, paste the full"
echo "     contents of firebase/firestore.rules and press Publish. Pinning a comment needs them."
echo "  2) Privacy Policy and Terms pages: after you push, open the repository on GitHub ->"
echo "     Settings -> Pages -> Source: Deploy from a branch -> main, folder /docs -> Save."
echo "     (A free account needs a public repository for Pages.) The address the app opens is"
echo "     the one constant kLegalBaseUrl in lib/core/legal.dart."
echo "  3) Run: flutter pub get   (the QR code package is new; the flow below does it)."
exit 0
